  function categoryLabel(kind) { const k = String(kind || 'Nature'); const known = {plant:'Plants',plants:'Plants',flower:'Flowers',flowers:'Flowers',tree:'Trees',trees:'Trees',bird:'Birds',birds:'Birds',butterfly:'Butterflies',butterflies:'Butterflies',animal:'Animals',animals:'Animals',insect:'Insects',insects:'Insects',mammal:'Mammals',mammals:'Mammals',fungus:'Fungi',fungi:'Fungi',fern:'Ferns',ferns:'Ferns',marine:'Marine life'}; return known[k.toLowerCase()] || k.charAt(0).toUpperCase() + k.slice(1); }
