  async function openDetail(id, personal = false, updateHash = true) { const entry = personal ? state.entries.find(e => e.id === id) : null; const item = personal ? byId.get(entry?.speciesId) : byId.get(String(id)); if(!item) return; activeDetail = {id:String(id), personal}; const photo = entry ? await getPhoto(entry.id) : item.image; const place = entry ? (validCoordinate(entry) && entry.latitude !== null ? 'Your private discovery' : 'Location not attached') : locality(item); const date = entry ? entry.createdAt : item.observedOn; const creditedURL = safeURL(item.sourceURL); const licenseURL = safeURL(item.photoLicenseURL); $('#detail-content').innerHTML = `<div class="detail-layout"><div class="detail-visual"><span class="detail-visual-tag">A LITTLE COMPANION</span><div class="detail-character-wrap"><img src="${esc(item.character)}" alt="${esc(item.name)} character"></div><figure class="detail-original">${photo ? `<img src="${esc(photo)}" alt="${entry ? 'Your photo of' : 'Original observation of'} ${esc(item.name)}">` : `<div class="photo-unavailable">${icon('camera')}<small>Local photo unavailable</small></div>`}<span>${entry ? 'YOUR PHOTO' : 'THE REAL LITTLE WONDER'}</span></figure></div><div class="detail-copy"><p class="eyebrow">${esc(categoryLabel(item.kind))} · ${entry ? 'YOUR FIELD NOTE' : 'CALIFORNIA FIELD GUIDE'}</p><h2>${esc(item.name)}</h2><p class="scientific-name">${esc(item.scientificName)}</p><div class="detail-facts"><div class="detail-fact">${icon('pin')}<div><strong>${esc(place)}</strong><small>${entry ? (entry.latitude !== null && entry.latitude !== undefined ? 'Optional location saved privately in this browser' : 'You can enjoy a discovery without sharing its location') : 'Approximate archive location, not a live sighting'}</small></div></div><div class="detail-fact">${icon('calendar')}<div><strong>${esc(dateLabel(date))}</strong><small>${entry ? 'Added to your Journal' : 'Original observation date'}</small></div></div></div>${entry?.note ? `<p class="detail-note">${esc(entry.note)}</p>` : ''}<div class="detail-actions"><button id="detail-save" class="button button-green">${icon(entry || isSaved(item.id) ? 'check' : 'book')}<span>${entry ? 'Remove from Journal' : isSaved(item.id) ? 'Saved · remove' : 'Save to my Journal'}</span></button><button id="detail-share" class="share-button" aria-label="Share this species">${icon('share')}</button></div><div class="credit-block">${entry ? '<p>Your photograph · stored only in this browser.</p>' : `<p>Photo: ${esc(item.sourceAttribution || item.author || 'See original record')}</p><p><a href="${esc(licenseURL)}" target="_blank" rel="noopener noreferrer">${esc(item.photoLicense || 'Photo license')}</a> · <a href="${esc(creditedURL)}" target="_blank" rel="noopener noreferrer">Original observation ↗</a></p>`}<p>Companion artwork: Nature Relay · AI-created illustration</p></div><p class="detail-honesty">${entry ? 'Species was chosen by you. The artwork is prepared in advance.' : 'A character introduces a real species. It is an illustration, not a scientific identification.'}</p></div></div>`; $('#detail-save').addEventListener('click', () => { if(entry) { state.entries = state.entries.filter(e => e.id !== entry.id); deletePhoto(entry.id); persist(); renderJournal(); closeDialog($('#detail-dialog')); toast('Discovery removed from this Journal.'); } else { if(isSaved(item.id)) { state.savedIds = state.savedIds.filter(v => v !== String(item.id)); toast('Removed from your Journal.'); } else { state.savedIds.unshift(String(item.id)); toast('A little wonder, saved to your Journal.'); } persist(); renderJournal(); renderDiscoveryList(); openDetail(item.id, false, false); } }); $('#detail-share').addEventListener('click', () => shareItem(item)); showDialog($('#detail-dialog')); if(updateHash && !entry) history.replaceState(null, '', '#species=' + encodeURIComponent(item.id)); }
  async function shareItem(item) { const u = new URL(location.href); u.hash = 'species=' + encodeURIComponent(item.id); const payload = {title:`Meet ${item.name} · Nature Relay`, text:`Look what I found in Nature Relay: ${item.name}.`, url:u.href}; try { if(navigator.share) { await navigator.share(payload); return; } if(navigator.clipboard && window.isSecureContext) { await navigator.clipboard.writeText(u.href); toast('Species link copied. Send it to a friend.'); return; } } catch(err) { if(err.name === 'AbortError') return; } const box = document.createElement('textarea'); box.value = u.href; box.style.position='fixed'; box.style.opacity='0'; document.body.appendChild(box); box.select(); let copied=false; try {copied=document.execCommand('copy');} catch {} box.remove(); toast(copied ? 'Species link copied. Send it to a friend.' : 'Copy the species link from your address bar.'); }
  let dbPromise;
  function photoDB() { if(!dbPromise) dbPromise = new Promise((resolve,reject) => { if(!window.indexedDB) return reject(new Error('Photo storage unavailable')); const request=indexedDB.open('nature-relay-photos',1); request.onupgradeneeded=()=>request.result.createObjectStore('photos'); request.onsuccess=()=>resolve(request.result); request.onerror=()=>reject(request.error); }); return dbPromise; }
  async function putPhoto(id,data) { try { const db=await photoDB(); await new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').put(data,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);}); return true; } catch { if(data.length > 700000) throw new Error('Photo storage is unavailable. Try a smaller photo or allow storage in your browser.'); photoFallback.set(id,data); try {localStorage.setItem(KEY+'-photo-'+id,data);} catch { throw new Error('Your browser could not store this photo. Free some space or allow site storage, then try again.');} return true; } }
  async function getPhoto(id) { if(photoFallback.has(id)) return photoFallback.get(id); try {const db=await photoDB();const result=await new Promise((resolve,reject)=>{const req=db.transaction('photos').objectStore('photos').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});if(result)return result;try{return localStorage.getItem(KEY+'-photo-'+id);}catch{return null;}} catch {try {return localStorage.getItem(KEY+'-photo-'+id);} catch {return null;}} }
