  function resizePhoto(file) { return new Promise((resolve,reject)=>{if(file.size>30000000)return reject(new Error('Please choose a photo smaller than 30 MB.'));const url=URL.createObjectURL(file);const img=new Image();img.onload=()=>{const scale=Math.min(1,960/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);resolve(canvas.toDataURL('image/jpeg',.78));};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('This photo format could not be opened. Please try a JPG, PNG, or WebP.'));};img.src=url;}); }
  function resetAddForm() { $('#add-form').reset(); currentPhoto=null; currentLocation=null; $('#photo-preview').hidden=true; $('#photo-preview').removeAttribute('src'); $('#photo-drop').classList.remove('has-photo'); $('#match-preview').hidden=true; $('#add-error').hidden=true; $('#photo-location-label').textContent='No location attached'; $('#add-location').textContent='Use my location'; $('#save-entry').disabled=false; }
