    $$('dialog').forEach(dialog=>{dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog(dialog);}});dialog.addEventListener('close',()=>{if(dialog.id==='detail-dialog'&&location.hash.startsWith('#species='))history.replaceState(null,'','#'+currentView);});});
    $('#search').addEventListener('input',event=>{query=event.target.value;renderDiscoveryList();});
    document.addEventListener('keydown',event=>{if(event.key==='/'&&!event.metaKey&&!event.ctrlKey&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!$$('dialog[open]').length){event.preventDefault();setView('map');$('#search').focus();}});
    $('#fit-map').addEventListener('click',()=>{const items=filteredCatalog().filter(validCoordinate);if(map&&items.length){map.fitBounds(L.latLngBounds(items.map(e=>[Number(e.latitude),Number(e.longitude)])),{padding:[60,60],maxZoom:12});}else toast('The map needs a connection. Your Journal is still available.');});
    $('#locate-map').addEventListener('click',async()=>{if(!map)return toast('Map unavailable. Try reconnecting.');const button=$('#locate-map');button.disabled=true;try{const pos=await geoPosition();map.setView([pos.coords.latitude,pos.coords.longitude],12);toast('Map centered near you. Your location has not been saved.');}catch(error){toast(geoError(error));}finally{button.disabled=false;}});
    $('#photo-input').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;photoBusy=true;$('#save-entry').disabled=true;$('#add-error').hidden=true;try{currentPhoto=await resizePhoto(file);$('#photo-preview').src=currentPhoto;$('#photo-preview').hidden=false;$('#photo-drop').classList.add('has-photo');}catch(error){currentPhoto=null;$('#add-error').textContent=error.message;$('#add-error').hidden=false;}finally{photoBusy=false;$('#save-entry').disabled=false;}});
    $('#species-select').addEventListener('change',event=>{const item=byId.get(event.target.value);const preview=$('#match-preview');preview.hidden=!item;if(item)preview.innerHTML=`<img src="${esc(item.character)}" alt="${esc(item.name)} companion"><div><strong>Your ${esc(item.name)} companion</strong><span>Prepared character art · matched to your choice</span></div>`;});
