    $('#add-form').addEventListener('submit',async event=>{event.preventDefault();if(photoBusy)return;const item=byId.get($('#species-select').value);if(!currentPhoto||!item){$('#add-error').textContent='Choose a photo and a species to save your discovery.';$('#add-error').hidden=false;return;}const button=$('#save-entry');button.disabled=true;const entry={id:'my-'+(crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2)),speciesId:String(item.id),createdAt:new Date().toISOString(),note:$('#entry-note').value.trim(),latitude:currentLocation?.latitude??null,longitude:currentLocation?.longitude??null};try{if(state.entries.length>=50)throw new Error('This browser Journal holds up to 50 of your photos. Remove an older photo to add another.');await putPhoto(entry.id,currentPhoto);state.entries.unshift(entry);if(!persist()){state.entries=state.entries.filter(e=>e.id!==entry.id);await deletePhoto(entry.id);throw new Error('Your browser could not save the Journal. Please allow storage for this site and try again.');}renderJournal();closeDialog($('#add-dialog'));setView('journal');toast('Your discovery has a home in your Journal.');openDetail(entry.id,true,false);}catch(error){$('#add-error').textContent=error.message;$('#add-error').hidden=false;}finally{button.disabled=false;}});
    window.addEventListener('hashchange',handleHash);
